148	  vgpr_cam (
149	    .clk                   (clk                 ),
150	    .rst_n                 (rst_n               ),
151	    .cam_wr_en_i           (cam_up_valid_reg    ),
152	    .cam_wr_addr_i         (cam_up_cu_id_reg    ),
153	    .cam_wr_data_i         (cam_up_vgpr_size_reg),
154	    .cam_wr_start_i        (cam_up_vgpr_strt_reg),
155	    .res_search_en_i       (alloc_valid_reg     ),
156	    .res_search_size_i     (alloc_vgpr_size_reg ),
157	    .res_search_out_o      (vgpr_search_out     ),
158	    .res_search_out_start_o(vgpr_cam_start_vec  )
159	    );
160	
161	  cam_allocator_neo #(
162	    .RES_ID_WIDTH(`SGPR_ID_WIDTH)
163	  )
164	  sgpr_cam (
165	    .clk                   (clk                 ),       
166	    .rst_n                 (rst_n               ),     
167	    .cam_wr_en_i           (cam_up_valid_reg    ),       
168	    .cam_wr_addr_i         (cam_up_cu_id_reg    ),     
169	    .cam_wr_data_i         (cam_up_sgpr_size_reg),
170	    .cam_wr_start_i        (cam_up_sgpr_strt_reg),
171	    .res_search_en_i       (alloc_valid_reg     ),      
172	    .res_search_size_i     (alloc_sgpr_size_reg ),       
173	    .res_search_out_o      (sgpr_search_out     ),    
174	    .res_search_out_start_o(sgpr_cam_start_vec  )   
175	    );
176	
177	  cam_allocator_neo #(
178	    .RES_ID_WIDTH(`LDS_ID_WIDTH)
179	  )
180	  lds_cam (
181	    .clk                   (clk                ),       
182	    .rst_n                 (rst_n              ),     
183	    .cam_wr_en_i           (cam_up_valid_reg   ),   
184	    .cam_wr_addr_i         (cam_up_cu_id_reg   ),     
185	    .cam_wr_data_i         (cam_up_lds_size_reg), 
186	    .cam_wr_start_i        (cam_up_lds_strt_reg),
187	    .res_search_en_i       (alloc_valid_reg    ),   
188	    .res_search_size_i     (alloc_lds_size_reg ),     
189	    .res_search_out_o      (lds_search_out     ),  
190	    .res_search_out_start_o(lds_cam_start_vec  ) 
191	    );
192	
193	  cam_allocator #(
194	    .RES_ID_WIDTH(`WF_COUNT_WIDTH)
195	  )
196	  wf_cam (
197	    .clk                   (clk                       ), 
198	    .rst_n                 (rst_n                     ), 
199	    .cam_wr_en_i           (cam_up_valid_reg          ), 
200	    .cam_wr_addr_i         (cam_up_cu_id_reg          ),   
201	    .cam_wr_data_i         ({1'b0,cam_up_wf_count_reg}),       
202	    .res_search_en_i       (alloc_valid_reg           ),   
203	    .res_search_size_i     ({1'b0,alloc_num_wf_reg}   ),     
204	    .res_search_out_o      (wf_search_out             )   
205	    );
206	
207	  cam_allocator #(
208	    .RES_ID_WIDTH(`WG_SLOT_ID_WIDTH)
209	  )
210	  wg_cam (
211	    .clk                   (clk                             ), 
212	    .rst_n                 (rst_n                           ), 
213	    .cam_wr_en_i           (cam_up_valid_reg                ),   
214	    .cam_wr_addr_i         (cam_up_cu_id_reg                ),   
215	    .cam_wr_data_i         (cam_up_wg_count_reg             ),
216	    .res_search_en_i       (alloc_valid_reg                 ),   
217	    .res_search_size_i     ({{`WG_SLOT_ID_WIDTH{1'b0}},1'b1}),     
218	    .res_search_out_o      (wg_search_out                   )   
219	    );
220	
221	  always@(posedge clk or negedge rst_n) begin
222	    if(!rst_n) begin
223	      pipeline_waiting <= 1'b0;
224	    end
225	    else if(encoded_cu_found_valid && !pipeline_waiting) begin
226	      pipeline_waiting <= 1'b1;
227	    end
228	    else if(dis_controller_alloc_ack_i) begin
229	      pipeline_waiting <= 1'b0;
230	    end
231	    else begin
232	      pipeline_waiting <= pipeline_waiting;
233	    end
234	  end
235	
236	  always@(posedge clk or negedge rst_n) begin
237	    if(!rst_n) begin
238	      alloc_valid_reg                 <= 'd0;                                  
239	      alloc_wg_id_reg                 <= 'd0;       
240	      alloc_num_wf_reg                <= 'd0;          
241	      alloc_vgpr_size_reg             <= 'd0;              
242	      alloc_sgpr_size_reg             <= 'd0;                
243	      alloc_lds_size_reg              <= 'd0;                  
244	      dis_controller_cu_busy_reg      <= 'd0;                    
245	      cam_wait_valid                  <= 'd0;                  
246	      cam_wait_wg_id                  <= 'd0;                        
247	      cam_wait_wf_count               <= 'd0;                        
248	      cam_wait_vgpr_size              <= 'd0;                        
249	      cam_wait_sgpr_size              <= 'd0;                    
250	      cam_wait_lds_size               <= 'd0;                    
251	      cam_wait_dis_controller_cu_busy <= 'd0;                          
252	      anded_cam_out_valid             <= 'd0;                            
253	      anded_cam_out                   <= 'd0;                                
254	      anded_cam_wg_id                 <= 'd0;                
255	      anded_cam_wf_count              <= 'd0;                
256	      anded_cam_vgpr_size             <= 'd0;            
257	      anded_cam_sgpr_size             <= 'd0;            
258	      anded_cam_lds_size              <= 'd0;            
259	      encoded_cu_out_valid            <= 'd0;                  
260	      encoded_cu_found_valid          <= 'd0;                  
261	      encoded_cu_id                   <= 'd0;                      
262	      encoded_cu_wg_id                <= 'd0;                      
263	      encoded_wf_count                <= 'd0;                
264	      encoded_vgpr_size               <= 'd0;                
265	      encoded_sgpr_size               <= 'd0;          
266	      encoded_lds_size                <= 'd0;            
267	      encoded_vgpr_start              <= 'd0;              
268	      encoded_sgpr_start              <= 'd0;            
269	      encoded_lds_start               <= 'd0;              
270	      size_ram_valid                  <= 'd0;            
271	      size_ram_cu_id_found            <= 'd0;          
272	      cu_id_out                       <= 'd0;        
273	      vgpr_start_out                  <= 'd0;        
274	      sgpr_start_out                  <= 'd0;          
275	      lds_start_out                   <= 'd0;          
276	      wg_id_out                       <= 'd0;          
277	      wf_count_out                    <= 'd0;            
278	      vgpr_size_out                   <= 'd0;        
279	      sgpr_size_out                   <= 'd0;            
280	      lds_size_out                    <= 'd0;          
281	    end
282	    else if(!pipeline_waiting) begin
283	      alloc_valid_reg                 <= dis_controller_start_alloc_i                                                                                           ;       
284	      alloc_wg_id_reg                 <= inflight_wg_buffer_alloc_wg_id_i                                                                                       ;    
285	      alloc_num_wf_reg                <= inflight_wg_buffer_alloc_num_wf_i                                                                                      ;   
286	      alloc_vgpr_size_reg             <= inflight_wg_buffer_alloc_vgpr_size_i                                                                                   ;   
287	      alloc_sgpr_size_reg             <= inflight_wg_buffer_alloc_sgpr_size_i                                                                                   ;   
288	      alloc_lds_size_reg              <= inflight_wg_buffer_alloc_lds_size_i                                                                                    ;   
289	      dis_controller_cu_busy_reg      <= dis_controller_cu_busy_i                                                                                               ; 
290	      cam_wait_valid                  <= alloc_valid_reg                                                                                                        ;       
291	      cam_wait_wg_id                  <= alloc_wg_id_reg                                                                                                        ;       
292	      cam_wait_wf_count               <= alloc_num_wf_reg                                                                                                       ;   
293	      cam_wait_vgpr_size              <= alloc_vgpr_size_reg                                                                                                    ;       
294	      cam_wait_sgpr_size              <= alloc_sgpr_size_reg                                                                                                    ;       
295	      cam_wait_lds_size               <= alloc_lds_size_reg                                                                                                     ;       
296	      cam_wait_dis_controller_cu_busy <= dis_controller_cu_busy_reg                                                                                             ;     
297	      anded_cam_out_valid             <= cam_wait_valid                                                                                                         ;       
298	      anded_cam_out                   <= vgpr_search_out & sgpr_search_out & lds_search_out & wf_search_out & wg_search_out & (~cam_wait_dis_controller_cu_busy);
299	      anded_cam_wg_id                 <= cam_wait_wg_id                                                                                                         ;   
300	      anded_cam_wf_count              <= cam_wait_wf_count                                                                                                      ;   
301	      anded_cam_vgpr_size             <= cam_wait_vgpr_size                                                                                                     ; 
302	      anded_cam_sgpr_size             <= cam_wait_sgpr_size                                                                                                     ;   
303	      anded_cam_lds_size              <= cam_wait_lds_size                                                                                                      ;     
304	      encoded_cu_out_valid            <= anded_cam_out_valid                                                                                                    ;       
305	      encoded_cu_found_valid          <= encoded_cu_found_valid_comb                                                                                            ;       
306	      encoded_cu_id                   <= encoded_cu_id_comb                                                                                                     ;   
307	      encoded_cu_wg_id                <= anded_cam_wg_id                                                                                                        ; 
308	      encoded_wf_count                <= anded_cam_wf_count                                                                                                     ;       
309	      encoded_vgpr_size               <= anded_cam_vgpr_size                                                                                                    ;   
310	      encoded_sgpr_size               <= anded_cam_sgpr_size                                                                                                    ;       
311	      encoded_lds_size                <= anded_cam_lds_size                                                                                                     ;       
312	      encoded_vgpr_start              <= encoded_vgpr_start_comb                                                                                                ;       
313	      encoded_sgpr_start              <= encoded_sgpr_start_comb                                                                                                ;       
314	      encoded_lds_start               <= encoded_lds_start_comb                                                                                                 ;       
315	      size_ram_valid                  <= encoded_cu_out_valid                                                                                                   ;     
316	      size_ram_cu_id_found            <= encoded_cu_found_valid                                                                                                 ;       
317	      cu_id_out                       <= encoded_cu_id                                                                                                          ;       
318	      vgpr_start_out                  <= encoded_vgpr_start                                                                                                     ;       
319	      sgpr_start_out                  <= encoded_sgpr_start                                                                                                     ;       
320	      lds_start_out                   <= encoded_lds_start                                                                                                      ;     
321	      wg_id_out                       <= encoded_cu_wg_id                                                                                                       ;   
322	      wf_count_out                    <= encoded_wf_count                                                                                                       ;     
323	      vgpr_size_out                   <= encoded_vgpr_size                                                                                                      ;       
324	      sgpr_size_out                   <= encoded_sgpr_size                                                                                                      ;     
325	      lds_size_out                    <= encoded_lds_size                                                                                                       ;       
326	    end
327	    else begin
328	      alloc_valid_reg                 <= alloc_valid_reg                ;  
329	      alloc_wg_id_reg                 <= alloc_wg_id_reg                ;
330	      alloc_num_wf_reg                <= alloc_num_wf_reg               ;
331	      alloc_vgpr_size_reg             <= alloc_vgpr_size_reg            ;
332	      alloc_sgpr_size_reg             <= alloc_sgpr_size_reg            ;
333	      alloc_lds_size_reg              <= alloc_lds_size_reg             ;
334	      dis_controller_cu_busy_reg      <= dis_controller_cu_busy_reg     ;
335	      cam_wait_valid                  <= cam_wait_valid                 ;
336	      cam_wait_wg_id                  <= cam_wait_wg_id                 ;
337	      cam_wait_wf_count               <= cam_wait_wf_count              ;
338	      cam_wait_vgpr_size              <= cam_wait_vgpr_size             ;
339	      cam_wait_sgpr_size              <= cam_wait_sgpr_size             ;
340	      cam_wait_lds_size               <= cam_wait_lds_size              ;
341	      cam_wait_dis_controller_cu_busy <= cam_wait_dis_controller_cu_busy;
342	      anded_cam_out_valid             <= anded_cam_out_valid            ;
343	      anded_cam_out                   <= anded_cam_out                  ;
344	      anded_cam_wg_id                 <= anded_cam_wg_id                ;
345	      anded_cam_wf_count              <= anded_cam_wf_count             ;
346	      anded_cam_vgpr_size             <= anded_cam_vgpr_size            ;
347	      anded_cam_sgpr_size             <= anded_cam_sgpr_size            ;
348	      anded_cam_lds_size              <= anded_cam_lds_size             ;
349	      encoded_cu_out_valid            <= encoded_cu_out_valid           ;
350	      encoded_cu_found_valid          <= encoded_cu_found_valid         ;
351	      encoded_cu_id                   <= encoded_cu_id                  ;
352	      encoded_cu_wg_id                <= encoded_cu_wg_id               ;
353	      encoded_wf_count                <= encoded_wf_count               ;
354	      encoded_vgpr_size               <= encoded_vgpr_size              ;
355	      encoded_sgpr_size               <= encoded_sgpr_size              ;
356	      encoded_lds_size                <= encoded_lds_size               ;
357	      encoded_vgpr_start              <= encoded_vgpr_start             ;
358	      encoded_sgpr_start              <= encoded_sgpr_start             ;
359	      encoded_lds_start               <= encoded_lds_start              ;
360	      size_ram_valid                  <= size_ram_valid                 ;
361	      size_ram_cu_id_found            <= size_ram_cu_id_found           ;
362	      cu_id_out                       <= cu_id_out                      ;
363	      vgpr_start_out                  <= vgpr_start_out                 ;
364	      sgpr_start_out                  <= sgpr_start_out                 ;
365	      lds_start_out                   <= lds_start_out                  ;
366	      wg_id_out                       <= wg_id_out                      ;
367	      wf_count_out                    <= wf_count_out                   ;
368	      vgpr_size_out                   <= vgpr_size_out                  ;
369	      sgpr_size_out                   <= sgpr_size_out                  ;
370	      lds_size_out                    <= lds_size_out                   ;
371	    end
372	  end
373	
374	  always@(posedge clk or negedge rst_n) begin
375	    if(!rst_n) begin
376	      cam_up_valid_reg     <= 'd0;  
377	      cam_up_cu_id_reg     <= 'd0;
378	      cam_up_vgpr_strt_reg <= 'd0;
379	      cam_up_vgpr_size_reg <= 'd0;
380	      cam_up_sgpr_strt_reg <= 'd0;
381	      cam_up_sgpr_size_reg <= 'd0;
382	      cam_up_lds_strt_reg  <= 'd0;
383	      cam_up_lds_size_reg  <= 'd0;
384	      cam_up_wf_count_reg  <= 'd0;
385	      cam_up_wg_count_reg  <= 'd0;
386	    end
387	    else begin
388	      cam_up_valid_reg     <= grt_cam_up_valid_i    ; 
389	      cam_up_cu_id_reg     <= grt_cam_up_cu_id_i    ;
390	      cam_up_vgpr_strt_reg <= grt_cam_up_vgpr_strt_i;
391	      cam_up_vgpr_size_reg <= grt_cam_up_vgpr_size_i;
392	      cam_up_sgpr_strt_reg <= grt_cam_up_sgpr_strt_i;
393	      cam_up_sgpr_size_reg <= grt_cam_up_sgpr_size_i;
394	      cam_up_lds_strt_reg  <= grt_cam_up_lds_strt_i ;
395	      cam_up_lds_size_reg  <= grt_cam_up_lds_size_i ;
396	      cam_up_wf_count_reg  <= grt_cam_up_wf_count_i ;
397	      cam_up_wg_count_reg  <= grt_cam_up_wg_count_i ;
398	    end
399	  end
400	
401	  always@(posedge clk or negedge rst_n) begin
402	    if(!rst_n) begin
403	      cu_initialized <= 1'b0;
404	    end
405	    else if(cam_up_valid_reg) begin
406	      cu_initialized[cam_up_cu_id_reg] <= 1'b1;
407	    end
408	    else begin
409	      cu_initialized <= cu_initialized;
410	    end
411	  end
412	
413	  assign allocator_cu_valid_o       = size_ram_valid       ;
414	  assign allocator_cu_rejected_o    = !size_ram_cu_id_found;
415	  assign allocator_cu_id_out_o      = cu_id_out            ;
416	  assign allocator_wg_id_out_o      = wg_id_out            ;
417	  assign allocator_wf_count_o       = wf_count_out         ;
418	  assign allocator_vgpr_size_out_o  = vgpr_size_out        ;
419	  assign allocator_sgpr_size_out_o  = sgpr_size_out        ;
420	  assign allocator_lds_size_out_o   = lds_size_out         ;
421	  assign allocator_vgpr_start_out_o = (!cu_initialized[cu_id_out]) ? 'd0 : vgpr_start_out;
422	  assign allocator_sgpr_start_out_o = (!cu_initialized[cu_id_out]) ? 'd0 : sgpr_start_out;
423	  assign allocator_lds_start_out_o  = (!cu_initialized[cu_id_out]) ? 'd0 : lds_start_out ;
424	
425	  //例化prefer_select
426	  prefer_select #(
427	    .RANGE   (`NUMBER_CU  ),
428	    .ID_WIDTH(`CU_ID_WIDTH)
429	  )
430	  U_prefer_select (
431	    .signal_i(anded_cam_out                    ),
432	    .prefer_i(anded_cam_wg_id[`CU_ID_WIDTH-1:0]),
433	    .valid_o (encoded_cu_found_valid_comb      ),
434	    .id_o    (encoded_cu_id_comb               )
435	    );
436	
437	  assign encoded_vgpr_start_comb = vgpr_cam_start_vec[(encoded_cu_id_comb+1)*`VGPR_ID_WIDTH-1-:`VGPR_ID_WIDTH];
438	  assign encoded_sgpr_start_comb = sgpr_cam_start_vec[(encoded_cu_id_comb+1)*`SGPR_ID_WIDTH-1-:`SGPR_ID_WIDTH];
439	  assign encoded_lds_start_comb  = lds_cam_start_vec[(encoded_cu_id_comb+1)*`LDS_ID_WIDTH-1-:`LDS_ID_WIDTH]   ;
440	
441	endmodule
442

