16	
17	module top_resource_table (
18	  input                                 clk                              , 
19	  input                                 rst_n                            ,
20	  input   [`WG_ID_WIDTH-1:0]            allocator_wg_id_out_i            ,
21	  input   [`WF_COUNT_WIDTH_PER_WG-1:0]  allocator_wf_count_i             ,
22	  input   [`CU_ID_WIDTH-1:0]            allocator_cu_id_out_i            ,
23	  input   [`VGPR_ID_WIDTH-1:0]          allocator_vgpr_start_out_i       ,
24	  input   [`VGPR_ID_WIDTH:0]            allocator_vgpr_size_out_i        ,
25	  input   [`SGPR_ID_WIDTH-1:0]          allocator_sgpr_start_out_i       ,
26	  input   [`SGPR_ID_WIDTH:0]            allocator_sgpr_size_out_i        ,
27	  input   [`LDS_ID_WIDTH-1:0]           allocator_lds_start_out_i        ,
28	  input   [`LDS_ID_WIDTH:0]             allocator_lds_size_out_i         ,
29	  input                                 dis_controller_wg_alloc_valid_i  ,
30	  input                                 dis_controller_wg_dealloc_valid_i,
31	  input   [`CU_ID_WIDTH-1:0]            gpu_interface_cu_id_i            ,
32	  input   [`WG_ID_WIDTH-1:0]            gpu_interface_dealloc_wg_id_i    ,
33	
34	  output                                grt_cam_up_valid_o               ,
35	  output  [`WF_COUNT_WIDTH-1:0]         grt_cam_up_wf_count_o            ,
36	  output  [`CU_ID_WIDTH-1:0]            grt_cam_up_cu_id_o               ,
37	  output  [`VGPR_ID_WIDTH-1:0]          grt_cam_up_vgpr_strt_o           ,
38	  output  [`VGPR_ID_WIDTH:0]            grt_cam_up_vgpr_size_o           ,
39	  output  [`SGPR_ID_WIDTH-1:0]          grt_cam_up_sgpr_strt_o           ,
40	  output  [`SGPR_ID_WIDTH:0]            grt_cam_up_sgpr_size_o           ,
41	  output  [`LDS_ID_WIDTH-1:0]           grt_cam_up_lds_strt_o            ,
42	  output  [`LDS_ID_WIDTH:0]             grt_cam_up_lds_size_o            ,
43	  output  [`WG_SLOT_ID_WIDTH:0]         grt_cam_up_wg_count_o            ,
44	  output                                grt_wg_alloc_done_o              ,
45	  output  [`WG_ID_WIDTH-1:0]            grt_wg_alloc_wg_id_o             ,
46	  output  [`CU_ID_WIDTH-1:0]            grt_wg_alloc_cu_id_o             ,
47	  output                                grt_wg_dealloc_done_o            ,
48	  output  [`WG_ID_WIDTH-1:0]            grt_wg_dealloc_wg_id_o           ,
49	  output  [`CU_ID_WIDTH-1:0]            grt_wg_dealloc_cu_id_o           
50	  );
51	
52	  reg   [`NUMBER_RES_TABLE-1:0]                       done_array                      ;
53	  reg   [`NUMBER_RES_TABLE*`WF_COUNT_WIDTH-1:0]       wf_count_array                  ;
54	  reg   [`NUMBER_RES_TABLE*(`WG_SLOT_ID_WIDTH+1)-1:0] wg_count_array                  ;
55	  reg   [`NUMBER_RES_TABLE*`VGPR_ID_WIDTH-1:0]        vgpr_start_array                ;
56	  reg   [`NUMBER_RES_TABLE*(`VGPR_ID_WIDTH+1)-1:0]    vgpr_size_array                 ;
57	  reg   [`NUMBER_RES_TABLE*`SGPR_ID_WIDTH-1:0]        sgpr_start_array                ;
58	  reg   [`NUMBER_RES_TABLE*(`SGPR_ID_WIDTH+1)-1:0]    sgpr_size_array                 ;
59	  reg   [`NUMBER_RES_TABLE*`LDS_ID_WIDTH-1:0]         lds_start_array                 ;
60	  reg   [`NUMBER_RES_TABLE*(`LDS_ID_WIDTH+1)-1:0]     lds_size_array                  ;
61	  reg   [`NUMBER_RES_TABLE*`WG_ID_WIDTH-1:0]          wg_id_array                     ;
62	  reg   [`NUMBER_RES_TABLE*`CU_ID_WIDTH-1:0]          cu_id_array                     ;
63	  reg   [`NUMBER_RES_TABLE-1:0]                       serviced_array                  ;
64	  reg   [`NUMBER_RES_TABLE-1:0]                       is_alloc_array                  ;
65	  reg   [`NUMBER_RES_TABLE-1:0]                       done_cancelled_array            ;
66	  reg   [`NUMBER_RES_TABLE-1:0]                       command_serviced_array_cancelled;
67	  
68	  //rt_group input
69	  wire  [`WG_ID_WIDTH-1:0]                        rt_group_wg_id     ;
70	  wire  [`CU_ID_WIDTH-`RES_TABLE_ADDR_WIDTH-1:0]  rt_group_cu_id     ;
71	  wire  [`NUMBER_RES_TABLE-1:0]                   rt_group_alloc_en  ;
72	  wire  [`NUMBER_RES_TABLE-1:0]                   rt_group_dealloc_en;
73	
74	  //rt_group output
75	  wire  [`NUMBER_RES_TABLE-1:0]                       rt_group_res_tbl_done;
76	  wire  [`NUMBER_RES_TABLE*`WF_COUNT_WIDTH-1:0]       rt_group_wf_count    ;
77	  wire  [`NUMBER_RES_TABLE*(`WG_SLOT_ID_WIDTH+1)-1:0] rt_group_wg_count    ;
78	  wire  [`NUMBER_RES_TABLE*`VGPR_ID_WIDTH-1:0]        rt_group_vgpr_start  ;
79	  wire  [`NUMBER_RES_TABLE*(`VGPR_ID_WIDTH+1)-1:0]    rt_group_vgpr_size   ;
80	  wire  [`NUMBER_RES_TABLE*`SGPR_ID_WIDTH-1:0]        rt_group_sgpr_start  ;
81	  wire  [`NUMBER_RES_TABLE*(`SGPR_ID_WIDTH+1)-1:0]    rt_group_sgpr_size   ;
82	  wire  [`NUMBER_RES_TABLE*`LDS_ID_WIDTH-1:0]         rt_group_lds_start   ;
83	  wire  [`NUMBER_RES_TABLE*(`LDS_ID_WIDTH+1)-1:0]     rt_group_lds_size    ;
84	
85	  wire  [`RES_TABLE_ADDR_WIDTH-1:0]               serviced_id          ;
86	  reg   [`RES_TABLE_ADDR_WIDTH-1:0]               serviced_id_reg      ;
87	  wire                                            serviced_id_valid    ;
88	  //reg                                             serviced_id_valid_reg;
89	  wire  [`NUMBER_RES_TABLE-1:0]                   req                  ;
90	  wire  [`NUMBER_RES_TABLE-1:0]                   grant                ;
91	  wire  [`NUMBER_RES_TABLE:0]                     grant_r              ;
92	
93	  reg                                             grt_cam_up_valid_reg   ;
94	  reg                                             grt_wg_alloc_done_reg  ;
95	  reg                                             grt_wg_dealloc_done_reg;
96	
97	  assign rt_group_wg_id = dis_controller_wg_alloc_valid_i ? allocator_wg_id_out_i : gpu_interface_dealloc_wg_id_i;
98	  assign rt_group_cu_id = dis_controller_wg_alloc_valid_i ? allocator_cu_id_out_i[`CU_ID_WIDTH-`RES_TABLE_ADDR_WIDTH-1:0] : gpu_interface_cu_id_i[`CU_ID_WIDTH-`RES_TABLE_ADDR_WIDTH-1:0];
99	
100	  genvar i;
101	  generate for(i=0;i<`NUMBER_RES_TABLE;i=i+1) begin : A1//有NUMBER_RES_TABLE个resource_table_group
102	    assign rt_group_alloc_en[i]   = (dis_controller_wg_alloc_valid_i && (allocator_cu_id_out_i[`CU_ID_WIDTH-1:`CU_ID_WIDTH-`RES_TABLE_ADDR_WIDTH] == i)) ? 1'b1 : 1'b0;
103	    assign rt_group_dealloc_en[i] = (dis_controller_wg_dealloc_valid_i && (gpu_interface_cu_id_i[`CU_ID_WIDTH-1:`CU_ID_WIDTH-`RES_TABLE_ADDR_WIDTH] == i)) ? 1'b1 : 1'b0;
104	
105	    resource_table_group #(
106	      .NUMBER_CU(`NUMBER_CU / `NUMBER_RES_TABLE)
107	    )
108	    rt_group (
109	      .clk             (clk                                                                    ),   
110	      .rst_n           (rst_n                                                                  ),   
111	                      
112	      .alloc_en_i      (rt_group_alloc_en[i]                                                   ),       
113	      .dealloc_en_i    (rt_group_dealloc_en[i]                                                 ),     
114	      .wg_id_i         (rt_group_wg_id                                                         ),     
115	      .sub_cu_id_i     (rt_group_cu_id                                                         ),   
116	      .lds_start_i     (allocator_lds_start_out_i                                              ), 
117	      .lds_size_i      (allocator_lds_size_out_i                                               ),   
118	      .vgpr_start_i    (allocator_vgpr_start_out_i                                             ), 
119	      .vgpr_size_i     (allocator_vgpr_size_out_i                                              ), 
120	      .sgpr_start_i    (allocator_sgpr_start_out_i                                             ),           
121	      .sgpr_size_i     (allocator_sgpr_size_out_i                                              ),         
122	      .wf_count_i      (allocator_wf_count_i                                                   ),     
123	      .done_cancelled_i(done_cancelled_array[i]                                                ),         
124	                        
125	      .res_tbl_done_o  (rt_group_res_tbl_done[i]                                               ),   
126	      .lds_start_o     (rt_group_lds_start[(i+1)*`LDS_ID_WIDTH-1-:`LDS_ID_WIDTH]               ),             
127	      .lds_size_o      (rt_group_lds_size[(i+1)*(`LDS_ID_WIDTH+1)-1-:(`LDS_ID_WIDTH+1)]        ),                 
128	      .vgpr_start_o    (rt_group_vgpr_start[(i+1)*`VGPR_ID_WIDTH-1-:`VGPR_ID_WIDTH]            ),                 
129	      .vgpr_size_o     (rt_group_vgpr_size[(i+1)*(`VGPR_ID_WIDTH+1)-1-:(`VGPR_ID_WIDTH+1)]     ),                 
130	      .sgpr_start_o    (rt_group_sgpr_start[(i+1)*`SGPR_ID_WIDTH-1-:`SGPR_ID_WIDTH]            ),         
131	      .sgpr_size_o     (rt_group_sgpr_size[(i+1)*(`SGPR_ID_WIDTH+1)-1-:(`SGPR_ID_WIDTH+1)]     ),               
132	      .wf_count_o      (rt_group_wf_count[(i+1)*`WF_COUNT_WIDTH-1-:`WF_COUNT_WIDTH]            ),       
133	      .wg_count_o      (rt_group_wg_count[(i+1)*(`WG_SLOT_ID_WIDTH+1)-1-:(`WG_SLOT_ID_WIDTH+1)])
134	      );
135	
136	    always@(posedge clk or negedge rst_n) begin
137	      if(!rst_n) begin
138	        wg_id_array[(i+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH] <= 'd0;
139	        cu_id_array[(i+1)*`CU_ID_WIDTH-1-:`CU_ID_WIDTH] <= 'd0;
140	        command_serviced_array_cancelled[i]             <= 'd0;
141	        done_cancelled_array[i]                         <= 'd0;
142	        is_alloc_array[i]                               <= 'd0;
143	        serviced_array[i]                               <= 'd0;
144	      end
145	      else if(dis_controller_wg_alloc_valid_i && (allocator_cu_id_out_i[`CU_ID_WIDTH-1:`CU_ID_WIDTH-`RES_TABLE_ADDR_WIDTH] == i)) begin
146	        wg_id_array[(i+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH] <= allocator_wg_id_out_i;
147	        cu_id_array[(i+1)*`CU_ID_WIDTH-1-:`CU_ID_WIDTH] <= allocator_cu_id_out_i;
148	        command_serviced_array_cancelled[i]             <= 1'b1                 ;
149	        done_cancelled_array[i]                         <= 1'b0                 ;
150	        is_alloc_array[i]                               <= 1'b1                 ;
151	      end
152	      else if(dis_controller_wg_dealloc_valid_i && (gpu_interface_cu_id_i[`CU_ID_WIDTH-1:`CU_ID_WIDTH-`RES_TABLE_ADDR_WIDTH] == i)) begin
153	        wg_id_array[(i+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH] <= gpu_interface_dealloc_wg_id_i;
154	        cu_id_array[(i+1)*`CU_ID_WIDTH-1-:`CU_ID_WIDTH] <= gpu_interface_cu_id_i        ;
155	        command_serviced_array_cancelled[i]             <= 1'b1                         ;
156	        done_cancelled_array[i]                         <= 1'b0                         ;
157	        is_alloc_array[i]                               <= 1'b0                         ;
158	      end
159	      else if(command_serviced_array_cancelled[i]) begin
160	        serviced_array[i]                   <= 1'b0;
161	        command_serviced_array_cancelled[i] <= 1'b0;
162	      end
163	      else if(serviced_id_valid && (i == serviced_id)) begin
164	        done_cancelled_array[i] <= 1'b1;
165	        serviced_array[i]       <= 1'b1;
166	      end
167	      else begin
168	        wg_id_array[(i+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH] <= wg_id_array[(i+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH]; 
169	        cu_id_array[(i+1)*`CU_ID_WIDTH-1-:`CU_ID_WIDTH] <= cu_id_array[(i+1)*`CU_ID_WIDTH-1-:`CU_ID_WIDTH];
170	        command_serviced_array_cancelled[i]             <= command_serviced_array_cancelled[i]            ;
171	        done_cancelled_array[i]                         <= done_cancelled_array[i]                        ;
172	        is_alloc_array[i]                               <= is_alloc_array[i]                              ;
173	        serviced_array[i]                               <= serviced_array[i]                              ;
174	      end
175	    end
176	
177	    //将rt_group输出寄存
178	    always@(posedge clk or negedge rst_n) begin
179	      if(!rst_n) begin
180	        done_array[i]                                                        <= 'd0;          
181	        wf_count_array[(i+1)*`WF_COUNT_WIDTH-1-:`WF_COUNT_WIDTH]             <= 'd0;              
182	        wg_count_array[(i+1)*(`WG_SLOT_ID_WIDTH+1)-1-:(`WG_SLOT_ID_WIDTH+1)] <= 'd0;                
183	        vgpr_start_array[(i+1)*`VGPR_ID_WIDTH-1-:`VGPR_ID_WIDTH]             <= 'd0;        
184	        vgpr_size_array[(i+1)*(`VGPR_ID_WIDTH+1)-1-:(`VGPR_ID_WIDTH+1)]      <= 'd0;              
185	        sgpr_start_array[(i+1)*`SGPR_ID_WIDTH-1-:`SGPR_ID_WIDTH]             <= 'd0;          
186	        sgpr_size_array[(i+1)*(`SGPR_ID_WIDTH+1)-1-:(`SGPR_ID_WIDTH+1)]      <= 'd0;            
187	        lds_start_array[(i+1)*`LDS_ID_WIDTH-1-:`LDS_ID_WIDTH]                <= 'd0;              
188	        lds_size_array[(i+1)*(`LDS_ID_WIDTH+1)-1-:(`LDS_ID_WIDTH+1)]         <= 'd0;      
189	      end
190	      else begin
191	        done_array[i]                                                        <= rt_group_res_tbl_done[i]                                               ; 
192	        wf_count_array[(i+1)*`WF_COUNT_WIDTH-1-:`WF_COUNT_WIDTH]             <= rt_group_wf_count[(i+1)*`WF_COUNT_WIDTH-1-:`WF_COUNT_WIDTH]            ;         
193	        wg_count_array[(i+1)*(`WG_SLOT_ID_WIDTH+1)-1-:(`WG_SLOT_ID_WIDTH+1)] <= rt_group_wg_count[(i+1)*(`WG_SLOT_ID_WIDTH+1)-1-:(`WG_SLOT_ID_WIDTH+1)];         
194	        vgpr_start_array[(i+1)*`VGPR_ID_WIDTH-1-:`VGPR_ID_WIDTH]             <= rt_group_vgpr_start[(i+1)*`VGPR_ID_WIDTH-1-:`VGPR_ID_WIDTH]            ;       
195	        vgpr_size_array[(i+1)*(`VGPR_ID_WIDTH+1)-1-:(`VGPR_ID_WIDTH+1)]      <= rt_group_vgpr_size[(i+1)*(`VGPR_ID_WIDTH+1)-1-:(`VGPR_ID_WIDTH+1)]     ;             
196	        sgpr_start_array[(i+1)*`SGPR_ID_WIDTH-1-:`SGPR_ID_WIDTH]             <= rt_group_sgpr_start[(i+1)*`SGPR_ID_WIDTH-1-:`SGPR_ID_WIDTH]            ;         
197	        sgpr_size_array[(i+1)*(`SGPR_ID_WIDTH+1)-1-:(`SGPR_ID_WIDTH+1)]      <= rt_group_sgpr_size[(i+1)*(`SGPR_ID_WIDTH+1)-1-:(`SGPR_ID_WIDTH+1)]     ;         
198	        lds_start_array[(i+1)*`LDS_ID_WIDTH-1-:`LDS_ID_WIDTH]                <= rt_group_lds_start[(i+1)*`LDS_ID_WIDTH-1-:`LDS_ID_WIDTH]               ;         
199	        lds_size_array[(i+1)*(`LDS_ID_WIDTH+1)-1-:(`LDS_ID_WIDTH+1)]         <= rt_group_lds_size[(i+1)*(`LDS_ID_WIDTH+1)-1-:(`LDS_ID_WIDTH+1)]        ;   
200	      end
201	    end  
202	  end
203	  endgenerate
204	
205	  //同时完成取低位为高优先级
206	  assign req               = done_array & (~serviced_array);
207	  assign serviced_id_valid = |req                          ;
208	  assign grant             = grant_r[`NUMBER_RES_TABLE-1:0];
209	
210	  fixed_pri_arb #(
211	    .ARB_WIDTH(`NUMBER_RES_TABLE+1)
212	  )
213	  U_fixed_pri_arb (
214	    .req  ({1'b0,req}  ),
215	    .grant(grant_r     )
216	    );
217	
218	  one2bin #(
219	    .ONE_WIDTH(`NUMBER_RES_TABLE    ),
220	    .BIN_WIDTH(`RES_TABLE_ADDR_WIDTH)
221	  )
222	  U_one2bin (
223	    .oh (grant      ),
224	    .bin(serviced_id)
225	    );
226	
227	  always@(posedge clk or negedge rst_n) begin
228	    if(!rst_n) begin
229	      serviced_id_reg       <= 'd0;
230	      //serviced_id_valid_reg <= 'd0;
231	    end
232	    else begin
233	      serviced_id_reg       <= serviced_id      ;
234	      //serviced_id_valid_reg <= serviced_id_valid;
235	    end
236	  end
237	
238	  //grt output
239	  assign grt_cam_up_vgpr_strt_o = vgpr_start_array[(serviced_id_reg+1)*`VGPR_ID_WIDTH-1-:`VGPR_ID_WIDTH]           ;
240	  assign grt_cam_up_vgpr_size_o = vgpr_size_array[(serviced_id_reg+1)*(`VGPR_ID_WIDTH+1)-1-:(`VGPR_ID_WIDTH+1)]     ;
241	  assign grt_cam_up_sgpr_strt_o = sgpr_start_array[(serviced_id_reg+1)*`SGPR_ID_WIDTH-1-:`SGPR_ID_WIDTH]            ;
242	  assign grt_cam_up_sgpr_size_o = sgpr_size_array[(serviced_id_reg+1)*(`SGPR_ID_WIDTH+1)-1-:(`SGPR_ID_WIDTH+1)]     ;
243	  assign grt_cam_up_lds_strt_o  = lds_start_array[(serviced_id_reg+1)*`LDS_ID_WIDTH-1-:`LDS_ID_WIDTH]               ;
244	  assign grt_cam_up_lds_size_o  = lds_size_array[(serviced_id_reg+1)*(`LDS_ID_WIDTH+1)-1-:(`LDS_ID_WIDTH+1)]        ;
245	  assign grt_cam_up_wf_count_o  = wf_count_array[(serviced_id_reg+1)*`WF_COUNT_WIDTH-1-:`WF_COUNT_WIDTH]            ;
246	  assign grt_cam_up_wg_count_o  = wg_count_array[(serviced_id_reg+1)*(`WG_SLOT_ID_WIDTH+1)-1-:(`WG_SLOT_ID_WIDTH+1)];
247	  assign grt_cam_up_cu_id_o     = cu_id_array[(serviced_id_reg+1)*`CU_ID_WIDTH-1-:`CU_ID_WIDTH]                     ;
248	
249	  assign grt_wg_alloc_cu_id_o   = cu_id_array[(serviced_id_reg+1)*`CU_ID_WIDTH-1-:`CU_ID_WIDTH]                     ;
250	  assign grt_wg_alloc_wg_id_o   = wg_id_array[(serviced_id_reg+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH]                     ;
251	  assign grt_wg_dealloc_cu_id_o = cu_id_array[(serviced_id_reg+1)*`CU_ID_WIDTH-1-:`CU_ID_WIDTH]                     ;
252	  assign grt_wg_dealloc_wg_id_o = wg_id_array[(serviced_id_reg+1)*`WG_ID_WIDTH-1-:`WG_ID_WIDTH]                     ;
253	
254	  always@(posedge clk or negedge rst_n) begin
255	    if(!rst_n) begin
256	      grt_cam_up_valid_reg    <= 'd0; 
257	      grt_wg_alloc_done_reg   <= 'd0;
258	      grt_wg_dealloc_done_reg <= 'd0;
259	    end
260	    else if(serviced_id_valid) begin
261	      if(is_alloc_array[serviced_id]) begin
262	        grt_cam_up_valid_reg              <= 1'b1;
263	        grt_wg_alloc_done_reg             <= 1'b1;
264	        grt_wg_dealloc_done_reg           <= 1'b0;
265	      end
266	      else begin
267	        grt_cam_up_valid_reg              <= 1'b1;
268	        grt_wg_alloc_done_reg             <= 1'b0;
269	        grt_wg_dealloc_done_reg           <= 1'b1;
270	      end
271	    end
272	    else begin
273	      grt_cam_up_valid_reg    <= 1'b0; 
274	      grt_wg_alloc_done_reg   <= 1'b0;
275	      grt_wg_dealloc_done_reg <= 1'b0;
276	    end
277	  end
278	
279	  assign grt_cam_up_valid_o     = grt_cam_up_valid_reg   ;
280	  assign grt_wg_alloc_done_o    = grt_wg_alloc_done_reg  ;
281	  assign grt_wg_dealloc_done_o  = grt_wg_dealloc_done_reg;
282	
283	endmodule
