module resource_table_group #(
  parameter NUMBER_CU = 2//NUMBER_CU / NUMBER_RES_TABLE
)(  
  input                                             clk             ,
  input                                             rst_n           ,

  input                                             alloc_en_i      ,
  input                                             dealloc_en_i    ,
  input   [`WG_ID_WIDTH-1:0]                        wg_id_i         ,
  input   [`CU_ID_WIDTH-`RES_TABLE_ADDR_WIDTH-1:0]  sub_cu_id_i     ,
