8	 * EITHER EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT,
9	 * MERCHANTABILITY OR FIT FOR A PARTICULAR PURPOSE.
10	 * See the Mulan PSL v2 for more details. */
11	// Author: Zhang, Qi
12	// Description:control model
13	
14	`timescale 1ns/1ns
15	
16	module dis_controller #(
17	  parameter NUMBER_CU             = 2                        ,
18	  parameter CU_ID_WIDTH           = 2                        ,
19	  parameter RES_TABLE_ADDR_WIDTH  = 1                        ,
20	  parameter NUMBER_RES_TABLE      = 1 << RES_TABLE_ADDR_WIDTH 
21	  )
22	  (
23	  input                    clk                                 ,
24	  input                    rst_n                               ,
25	
26	  input                    inflight_wg_buffer_alloc_valid_i    ,
27	  input                    inflight_wg_buffer_alloc_available_i,
28	  input                    allocator_cu_valid_i                ,
29	  input                    allocator_cu_rejected_i             ,
30	  input  [CU_ID_WIDTH-1:0] allocator_cu_id_out_i               ,
31	  input                    grt_wg_alloc_done_i                 ,
32	  input                    grt_wg_dealloc_done_i               ,
33	  input  [CU_ID_WIDTH-1:0] grt_wg_alloc_cu_id_i                ,
34	  input  [CU_ID_WIDTH-1:0] grt_wg_dealloc_cu_id_i              ,
35	  input                    gpu_interface_alloc_available_i     ,
36	  input                    gpu_interface_dealloc_available_i   ,
37	  input  [CU_ID_WIDTH-1:0] gpu_interface_cu_id_i               ,
38	
39	  output                   dis_controller_start_alloc_o        ,
40	  output                   dis_controller_alloc_ack_o          ,
41	  output                   dis_controller_wg_alloc_valid_o     ,
42	  output                   dis_controller_wg_dealloc_valid_o   ,
43	  output                   dis_controller_wg_rejected_valid_o  ,
44	  output [NUMBER_CU-1:0]   dis_controller_cu_busy_o              
45	  );
46	
47	  parameter ALLOC_NUM_STATES      = 'h4;
48	
49	  parameter ST_AL_IDLE            = 4'h0,
50	            ST_AL_ALLOC           = 4'h2,
51	            ST_AL_HANDLE_RESULT   = 4'h4,
52	            ST_AL_ACK_PROPAGATION = 4'h8;                         
53	
54	  reg [ALLOC_NUM_STATES-1:0] alloc_st;
55	  wire [NUMBER_CU-1:0] cus_allocating;
56	  reg [NUMBER_RES_TABLE- 1:0] cu_groups_allocating;
57	  reg [CU_ID_WIDTH-1:0] alloc_waiting_cu_id;
58	  reg alloc_waiting;
59	  reg dis_controller_start_alloc_i;
60	  reg dis_controller_alloc_ack_i; 
61	  reg dis_controller_wg_alloc_valid_i; 
62	  reg dis_controller_wg_dealloc_valid_i; 
63	  reg dis_controller_wg_rejected_valid_i; 
64	  wire [RES_TABLE_ADDR_WIDTH-1:0] gpu_interface_cu_res_tbl_addr;
65	
66	  assign dis_controller_start_alloc_o       = dis_controller_start_alloc_i;
67	  assign dis_controller_alloc_ack_o         = dis_controller_alloc_ack_i; 
68	  assign dis_controller_wg_alloc_valid_o    = dis_controller_wg_alloc_valid_i; 
69	  assign dis_controller_wg_dealloc_valid_o  = dis_controller_wg_dealloc_valid_i; 
70	  assign dis_controller_wg_rejected_valid_o = dis_controller_wg_rejected_valid_i; 
71	
72	  assign gpu_interface_cu_res_tbl_addr = gpu_interface_cu_id_i[CU_ID_WIDTH-1:CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH];
73	
74	  always @(posedge clk or negedge rst_n) begin
75	    if(!rst_n) begin
76	      alloc_st <= ST_AL_IDLE;
77	      alloc_waiting_cu_id <= 'h0;
78	      dis_controller_start_alloc_i <= 'h0;
79	      dis_controller_alloc_ack_i <= 'h0;
80	    end 
81	    else begin
82	      case(alloc_st)
83	      ST_AL_IDLE            : 
84	                              begin
85	                                if(inflight_wg_buffer_alloc_valid_i && !(&cu_groups_allocating)) begin
86	                                  alloc_st <= ST_AL_ALLOC;
87	                                  alloc_waiting_cu_id <= alloc_waiting_cu_id;
88	                                  dis_controller_start_alloc_i <= 'h1;
89	                                  dis_controller_alloc_ack_i <= 'h0;
90	                                end 
91	                                else begin
92	                                  alloc_st <= alloc_st;
93	                                  alloc_waiting_cu_id <= alloc_waiting_cu_id;
94	                                  dis_controller_start_alloc_i <= 'h0;
95	                                  dis_controller_alloc_ack_i <= 'h0;
96	                                end 
97	                              end 
98	      ST_AL_ALLOC           :   
99	                              begin
100	                                if(allocator_cu_valid_i) begin
101	                                  alloc_st <= ST_AL_HANDLE_RESULT;
102	                                  alloc_waiting_cu_id <= allocator_cu_id_out_i;
103	                                  dis_controller_start_alloc_i <= 'h0;
104	                                  dis_controller_alloc_ack_i <= 'h0;
105	                                end 
106	                                else begin
107	                                  alloc_st <= alloc_st;
108	                                  alloc_waiting_cu_id <= alloc_waiting_cu_id;
109	                                  dis_controller_start_alloc_i <= 'h0;
110	                                  dis_controller_alloc_ack_i <= 'h0;
111	                                end 
112	                              end 
113	      ST_AL_HANDLE_RESULT   :   
114	                              begin
115	                                if(!alloc_waiting) begin
116	                                  alloc_st <= ST_AL_ACK_PROPAGATION;
117	                                  alloc_waiting_cu_id <= alloc_waiting_cu_id;
118	                                  dis_controller_start_alloc_i <= 'h0;
119	                                  dis_controller_alloc_ack_i <= 'h1;
120	                                end 
121	                                else begin
122	                                  alloc_st <= alloc_st;
123	                                  alloc_waiting_cu_id <= alloc_waiting_cu_id;
124	                                  dis_controller_start_alloc_i <= 'h0;
125	                                  dis_controller_alloc_ack_i <= 'h0;
126	                                end 
127	                              end 
128	      ST_AL_ACK_PROPAGATION : 
129	                              begin
130	                                alloc_st <= ST_AL_IDLE;
131	                                alloc_waiting_cu_id <= alloc_waiting_cu_id;
132	                                dis_controller_start_alloc_i <= 'h0;
133	                                dis_controller_alloc_ack_i <= 'h0;
134	                              end 
135	      default               :
136	                              begin
137	                                alloc_st <= ST_AL_IDLE;
138	                                alloc_waiting_cu_id <= alloc_waiting_cu_id;
139	                                dis_controller_start_alloc_i <= 'h0;
140	                                dis_controller_alloc_ack_i <= 'h0;
141	                              end 
142	      endcase
143	    end 
144	  end 
145	
146	  always @(posedge clk or negedge rst_n) begin
147	    if(!rst_n) begin
148	      dis_controller_wg_dealloc_valid_i <= 'h0;
149	      dis_controller_wg_alloc_valid_i <= 'h0;
150	      dis_controller_wg_rejected_valid_i <= 'h0;
151	    end   
152	    else if(gpu_interface_dealloc_available_i && !cu_groups_allocating[gpu_interface_cu_res_tbl_addr]) begin
153	      dis_controller_wg_dealloc_valid_i <= 'h1;
154	      dis_controller_wg_alloc_valid_i <= 'h0;
155	      dis_controller_wg_rejected_valid_i <= 'h0;
156	    end 
157	    else if(alloc_waiting && !cu_groups_allocating[alloc_waiting_cu_id[CU_ID_WIDTH-1:CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH]]) begin
158	      if(allocator_cu_rejected_i) begin
159	        dis_controller_wg_dealloc_valid_i <= 'h0;
160	        dis_controller_wg_alloc_valid_i <= 'h0;
161	        dis_controller_wg_rejected_valid_i <= 'h1;
162	      end 
163	      else if(gpu_interface_alloc_available_i && inflight_wg_buffer_alloc_available_i) begin
164	        dis_controller_wg_dealloc_valid_i <= 'h0;
165	        dis_controller_wg_alloc_valid_i <= 'h1;
166	        dis_controller_wg_rejected_valid_i <= 'h0;
167	      end 
168	      else begin
169	        dis_controller_wg_dealloc_valid_i <= 'h0;
170	        dis_controller_wg_alloc_valid_i <= 'h0;
171	        dis_controller_wg_rejected_valid_i <= 'h0;
172	      end 
173	    end 
174	    else begin
175	      dis_controller_wg_dealloc_valid_i <= 'h0;
176	      dis_controller_wg_alloc_valid_i <= 'h0;
177	      dis_controller_wg_rejected_valid_i <= 'h0;
178	    end 
179	  end 
180	
181	  always @(posedge clk or negedge rst_n) begin
182	    if(!rst_n) begin
183	      alloc_waiting <= 'h0;
184	    end 
185	    else if((alloc_st == ST_AL_ALLOC) && allocator_cu_valid_i) begin
186	      alloc_waiting <= 'h1;
187	    end 
188	    else if(alloc_waiting && !cu_groups_allocating[alloc_waiting_cu_id[CU_ID_WIDTH-1:CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH]]) begin
189	      alloc_waiting <= 'h0;
190	    end 
191	    else begin
192	      alloc_waiting <= alloc_waiting;
193	    end 
194	  end 
195	
196	  always @(posedge clk or negedge rst_n) begin
197	    if(!rst_n) begin
198	      cu_groups_allocating <= 'h0;
199	    end 
200	    else if(gpu_interface_dealloc_available_i && !cu_groups_allocating[gpu_interface_cu_res_tbl_addr]) begin
201	      cu_groups_allocating[gpu_interface_cu_res_tbl_addr] <= 'h1;
202	    end
203	    else if(alloc_waiting && !cu_groups_allocating[alloc_waiting_cu_id[CU_ID_WIDTH-1:CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH]]
204	            && allocator_cu_rejected_i) begin
205	      cu_groups_allocating <= cu_groups_allocating;
206	    end
207	    else if(alloc_waiting && !cu_groups_allocating[alloc_waiting_cu_id[CU_ID_WIDTH-1:CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH]] 
208	            && gpu_interface_alloc_available_i && inflight_wg_buffer_alloc_available_i) begin
209	      cu_groups_allocating[alloc_waiting_cu_id[CU_ID_WIDTH-1:CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH]] <= 'h1;
210	    end 
211	    else if(grt_wg_alloc_done_i) begin
212	      cu_groups_allocating[grt_wg_alloc_cu_id_i[CU_ID_WIDTH-1:CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH]] <= 'h0;
213	    end 
214	    else if(grt_wg_dealloc_done_i) begin
215	      cu_groups_allocating[grt_wg_dealloc_cu_id_i[CU_ID_WIDTH-1:CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH]] <= 'h0;
216	    end 
217	    else begin
218	      cu_groups_allocating <= cu_groups_allocating;
219	    end 
220	  end   
221	
222	  genvar i;
223	  generate for(i=0;i<NUMBER_CU;i=i+1) begin:B1
224	    assign cus_allocating[i] = cu_groups_allocating[(i>>(CU_ID_WIDTH-RES_TABLE_ADDR_WIDTH))];
225	  end
226	  endgenerate 
227	
228	  assign dis_controller_cu_busy_o = cus_allocating;
229	
230	endmodule
