11	// Author: Gu, Zihan
12	// Description:
13	
14	`timescale 1ns/1ns
15	`include "define.v"
16	
17	module resource_table #(
18	  parameter NUMBER_CU        = 2,
19	  parameter CU_ID_WIDTH      = 1,
20	  parameter RES_ID_WIDTH     = 10,
21	  parameter NUMBER_RES_SLOTS = 1024
22	  )(
23	  input                               clk                     ,
24	  input                               rst_n                   ,
25	
26	  input                               alloc_res_en_i          ,
27	  input                               dealloc_res_en_i        ,
28	  input   [CU_ID_WIDTH-1:0]           alloc_cu_id_i           ,
29	  input   [CU_ID_WIDTH-1:0]           dealloc_cu_id_i         ,
30	  input   [`WG_SLOT_ID_WIDTH-1:0]     alloc_wg_slot_id_i      ,
31	  input   [`WG_SLOT_ID_WIDTH-1:0]     dealloc_wg_slot_id_i    ,
32	  input   [RES_ID_WIDTH:0]            alloc_res_size_i        ,
33	  input   [RES_ID_WIDTH-1:0]          alloc_res_start_i       ,
34	
35	  output                              res_table_done_o        ,
36	  output  [RES_ID_WIDTH:0]            cam_biggest_space_size_o,
37	  output  [RES_ID_WIDTH-1:0]          cam_biggest_space_addr_o
38	  );
39	
40	  localparam  WG_SLOT_ID_WIDTH_TABLE = `WG_SLOT_ID_WIDTH + 1                            ;
41	  localparam  TABLE_ADDR_WIDTH       = WG_SLOT_ID_WIDTH_TABLE + CU_ID_WIDTH             ;
42	  localparam  TABLE_ENTRY_WIDTH      = 2 * WG_SLOT_ID_WIDTH_TABLE + 2 * RES_ID_WIDTH + 1;
43	
44	  localparam  RES_STRT_L   = 0                                        ;
45	  localparam  RES_STRT_H   = RES_ID_WIDTH - 1                         ;
46	  localparam  RES_SIZE_L   = RES_STRT_H + 1                           ;
47	  localparam  RES_SIZE_H   = RES_SIZE_L + RES_ID_WIDTH                ;
48	  localparam  PREV_ENTRY_L = RES_SIZE_H + 1                           ;
49	  localparam  PREV_ENTRY_H = PREV_ENTRY_L + WG_SLOT_ID_WIDTH_TABLE - 1;
50	  localparam  NEXT_ENTRY_L = PREV_ENTRY_H + 1                         ;
51	  localparam  NEXT_ENTRY_H = NEXT_ENTRY_L + WG_SLOT_ID_WIDTH_TABLE - 1;
52	
53	  localparam  NUM_ENTRIES              = NUMBER_CU * (`NUMBER_WF_SLOTS + 1)                ;
54	  localparam  RES_TABLE_END_TABLE      = (1 << WG_SLOT_ID_WIDTH_TABLE) - 1                 ;
55	  localparam  RES_TABLE_END_TABLE_U    = RES_TABLE_END_TABLE[WG_SLOT_ID_WIDTH_TABLE-1:0]   ;
56	  localparam  RES_TABLE_HEAD_POINTER   = (1 << WG_SLOT_ID_WIDTH_TABLE) - 2                 ; 
57	  localparam  RES_TABLE_HEAD_POINTER_U = RES_TABLE_HEAD_POINTER[WG_SLOT_ID_WIDTH_TABLE-1:0];
58	
59	  //the states of four state machine
60	  //main state machine
61	  localparam  ST_M_IDLE     = 4'b0001;
62	  localparam  ST_M_ALLOC    = 4'b0010;
63	  localparam  ST_M_DEALLOC  = 4'b0100;
64	  localparam  ST_M_FIND_MAX = 4'b1000;
65	  reg   [3:0]   m_state;
66	  //reg   [3:0]   m_curr_state;
67	  //reg   [3:0]   m_next_state;
68	
69	  //alloc state machine
70	  localparam  ST_A_IDLE              = 4'b0001;
71	  localparam  ST_A_FIND_POSITION     = 4'b0010;
72	  localparam  ST_A_UPDATE_PREV_ENTRY = 4'b0100;
73	  localparam  ST_A_WRITE_NEW_ENTRY   = 4'b1000;
74	  reg   [3:0]   a_state;
75	
76	  //dealloc state machine
77	  localparam  ST_D_IDLE              = 5'b00001;
78	  localparam  ST_D_READ_PREV_ENTRY   = 5'b00010;
79	  localparam  ST_D_READ_NEXT_ENTRY   = 5'b00100;
80	  localparam  ST_D_UPDATE_PREV_ENTRY = 5'b01000;
81	  localparam  ST_D_UPDATE_NEXT_ENTRY = 5'b10000;
82	  reg   [4:0]   d_state;
83	
84	  //find max state machine
85	  localparam  ST_F_IDLE       = 4'b0001;
86	  localparam  ST_F_FIRST_ITEM = 4'b0010;
87	  localparam  ST_F_SEARCHING  = 4'b0100;
88	  localparam  ST_F_LAST_ITEM  = 4'b1000;
89	  reg   [3:0]   f_state;
90	
91	  //input reg
92	  reg                                 res_table_done_reg      ;
93	  reg                                 alloc_res_en_reg        ;
94	  reg                                 dealloc_res_en_reg      ;
95	  reg   [CU_ID_WIDTH-1:0]             alloc_cu_id_reg         ;
96	  reg   [CU_ID_WIDTH-1:0]             dealloc_cu_id_reg       ;
97	  reg   [WG_SLOT_ID_WIDTH_TABLE-1:0]  alloc_wg_slot_id_reg    ;
98	  reg   [WG_SLOT_ID_WIDTH_TABLE-1:0]  dealloc_wg_slot_id_reg  ;
99	  reg   [RES_ID_WIDTH:0]              alloc_res_size_reg      ;
100	  reg   [RES_ID_WIDTH-1:0]            alloc_res_start_reg     ;
101	
102	  //ram of resource table
103	  reg   [NUM_ENTRIES*TABLE_ENTRY_WIDTH-1:0]      resource_table_ram    ;
104	  reg   [NUMBER_CU*WG_SLOT_ID_WIDTH_TABLE-1:0]   table_head_pointer    ;
105	  reg   [WG_SLOT_ID_WIDTH_TABLE-1:0]             table_head_pointer_reg;
106	
107	  //datapath reg
108	  reg   [TABLE_ENTRY_WIDTH-1:0]       res_table_wr_reg     ;
109	  reg   [TABLE_ENTRY_WIDTH-1:0]       res_table_rd_reg     ;
110	  reg   [TABLE_ENTRY_WIDTH-1:0]       res_table_last_rd_reg;
111	  reg   [CU_ID_WIDTH-1:0]             res_addr_cu_id       ;
112	  reg   [WG_SLOT_ID_WIDTH_TABLE-1:0]  res_addr_wg_slot     ;
113	  reg                                 res_table_rd_en      ;
114	  reg                                 res_table_wr_en      ;
115	  reg                                 res_table_rd_valid   ;
116	  reg   [RES_ID_WIDTH:0]              res_table_max_size   ;
117	  reg   [RES_ID_WIDTH-1:0]            res_table_max_start  ;
118	
119	  //control signals
120	  reg                                 alloc_start       ;
121	  reg                                 dealloc_start     ;
122	  reg                                 find_max_start    ;
123	  reg                                 alloc_done        ;
124	  reg                                 dealloc_done      ;
125	  reg                                 find_max_done     ;
126	  reg                                 new_entry_is_last ;
127	  reg                                 new_entry_is_first;
128	  reg                                 rem_entry_is_last ;
129	  reg                                 rem_entry_is_first;
130	  reg   [NUMBER_CU-1:0]               cu_initialized    ;
131	  reg                                 cu_initialized_reg;
132	
133	  assign  res_table_done_o = res_table_done_reg;
134	
135	  always@(posedge clk or negedge rst_n) begin
136	    if(!rst_n) begin
137	      alloc_res_en_reg   <= 'd0;
138	      dealloc_res_en_reg <= 'd0;
139	      res_table_rd_valid <= 'd0;
140	    end
141	    else begin
142	      alloc_res_en_reg   <= alloc_res_en_i  ;
143	      dealloc_res_en_reg <= dealloc_res_en_i;
144	      res_table_rd_valid <= res_table_rd_en ;
145	    end
146	  end
147	
148	  always@(posedge clk or negedge rst_n) begin
149	    if(!rst_n) begin
150	      alloc_cu_id_reg        <= 'd0;
151	      alloc_wg_slot_id_reg   <= 'd0;
152	      alloc_res_size_reg     <= 'd0;
153	      alloc_res_start_reg    <= 'd0;
154	      res_addr_cu_id         <= 'd0;
155	      dealloc_cu_id_reg      <= 'd0;
156	      dealloc_wg_slot_id_reg <= 'd0;
157	    end
158	    else if(alloc_res_en_i) begin
159	      alloc_cu_id_reg        <= alloc_cu_id_i     ;
160	      alloc_wg_slot_id_reg   <= alloc_wg_slot_id_i;
161	      alloc_res_size_reg     <= alloc_res_size_i  ;
162	      alloc_res_start_reg    <= alloc_res_start_i ;
163	      res_addr_cu_id         <= alloc_cu_id_i     ;
164	    end
165	    else if(dealloc_res_en_i) begin
166	      dealloc_cu_id_reg      <= dealloc_cu_id_i     ;
167	      dealloc_wg_slot_id_reg <= dealloc_wg_slot_id_i;
168	      res_addr_cu_id         <= dealloc_cu_id_i     ;
169	    end
170	    else begin
171	      alloc_cu_id_reg        <= alloc_cu_id_reg       ; 
172	      alloc_wg_slot_id_reg   <= alloc_wg_slot_id_reg  ; 
173	      alloc_res_size_reg     <= alloc_res_size_reg    ; 
174	      alloc_res_start_reg    <= alloc_res_start_reg   ; 
175	      res_addr_cu_id         <= res_addr_cu_id        ; 
176	      dealloc_cu_id_reg      <= dealloc_cu_id_reg     ; 
177	      dealloc_wg_slot_id_reg <= dealloc_wg_slot_id_reg; 
178	    end
179	  end
180	
181	  //main state machine of the resource table
182	  always@(posedge clk or negedge rst_n) begin
183	    if(!rst_n) begin
184	      alloc_start        <= 1'b0     ;
185	      dealloc_start      <= 1'b0     ;
186	      find_max_start     <= 1'b0     ;
187	      res_table_done_reg <= 1'b0     ;
188	      m_state            <= ST_M_IDLE;
189	    end
190	    else begin
191	      case(m_state)
192	        ST_M_IDLE : begin
193	          if(alloc_res_en_reg) begin
194	            alloc_start        <= 1'b1      ;
195	            dealloc_start      <= 1'b0      ;
196	            find_max_start     <= 1'b0      ;
197	            res_table_done_reg <= 1'b0      ;
198	            m_state            <= ST_M_ALLOC;
199	          end
200	          else if(dealloc_res_en_reg) begin
201	            alloc_start        <= 1'b0        ;
202	            dealloc_start      <= 1'b1        ;
203	            find_max_start     <= 1'b0        ;
204	            res_table_done_reg <= 1'b0        ;
205	            m_state            <= ST_M_DEALLOC;
206	          end
207	          else begin
208	            alloc_start        <= 1'b0   ;  
209	            dealloc_start      <= 1'b0   ;
210	            find_max_start     <= 1'b0   ;
211	            res_table_done_reg <= 1'b0   ;
212	            m_state            <= m_state;
213	          end
214	        end
215	
216	        ST_M_ALLOC : begin
217	          if(alloc_done) begin
218	            alloc_start        <= 1'b0         ;
219	            dealloc_start      <= 1'b0         ;
220	            find_max_start     <= 1'b1         ;
221	            res_table_done_reg <= 1'b0         ;
222	            m_state            <= ST_M_FIND_MAX;
223	          end
224	          else begin
225	            alloc_start        <= 1'b0   ;
226	            dealloc_start      <= 1'b0   ;
227	            find_max_start     <= 1'b0   ;
228	            res_table_done_reg <= 1'b0   ;
229	            m_state            <= m_state;
230	          end
231	        end
232	
233	        ST_M_DEALLOC : begin
234	          if(dealloc_done) begin
235	            alloc_start        <= 1'b0         ;
236	            dealloc_start      <= 1'b0         ;
237	            find_max_start     <= 1'b1         ;
238	            res_table_done_reg <= 1'b0         ;
239	            m_state            <= ST_M_FIND_MAX;
240	          end
241	          else begin
242	            alloc_start        <= 1'b0   ; 
243	            dealloc_start      <= 1'b0   ;
244	            find_max_start     <= 1'b0   ;
245	            res_table_done_reg <= 1'b0   ;
246	            m_state            <= m_state;
247	          end
248	        end
249	
250	        ST_M_FIND_MAX : begin
251	          if(find_max_done) begin
252	            alloc_start        <= 1'b0     ;
253	            dealloc_start      <= 1'b0     ;
254	            find_max_start     <= 1'b0     ;
255	            res_table_done_reg <= 1'b1     ;
256	            m_state            <= ST_M_IDLE;
257	          end
258	          else begin
259	            alloc_start        <= 1'b0   ; 
260	            dealloc_start      <= 1'b0   ;
261	            find_max_start     <= 1'b0   ;
262	            res_table_done_reg <= 1'b0   ;
263	            m_state            <= m_state;
264	          end
265	        end
266	
267	        default : begin
268	          alloc_start        <= 1'b0     ;
269	          dealloc_start      <= 1'b0     ;
270	          find_max_start     <= 1'b0     ;
271	          res_table_done_reg <= 1'b0     ;
272	          m_state            <= ST_M_IDLE;
273	        end
274	      endcase
275	    end
276	  end
277	
278	  // All state machines share the same resource table, 
279	  // so there can be onle one machine out of IDLE state at a given time.
280	  // alloc state machine
281	  always@(posedge clk or negedge rst_n) begin
282	    if(!rst_n) begin
283	      alloc_done             <= 1'b0     ;
284	      new_entry_is_first     <= 1'b0     ;
285	      new_entry_is_last      <= 1'b0     ;
286	      a_state                <= ST_A_IDLE;
287	    end
288	    else begin
289	      case(a_state)
290	        ST_A_IDLE : begin
291	          if(alloc_start) begin// Start looking for the new entry positon on
292	            if(table_head_pointer_reg == RES_TABLE_END_TABLE_U || !cu_initialized_reg) begin// Table is clear or cu was not initialized
293	              alloc_done         <= 1'b0                ;
294	              new_entry_is_first <= 1'b1                ;
295	              new_entry_is_last  <= 1'b1                ;
296	              a_state            <= ST_A_WRITE_NEW_ENTRY;
297	            end
298	            else begin
299	              alloc_done         <= 1'b0              ;
300	              new_entry_is_last  <= 1'b0              ;
301	              new_entry_is_first <= 1'b0              ;
302	              a_state            <= ST_A_FIND_POSITION;
303	            end
304	          end
305	          else begin
306	            alloc_done         <= 1'b0              ;
307	            new_entry_is_first <= new_entry_is_first;
308	            new_entry_is_last  <= new_entry_is_last ;
309	            a_state            <= a_state           ;
310	          end
311	        end
312	
313	        ST_A_FIND_POSITION : begin
314	          if(res_table_rd_valid) begin//Look for the entry position
315	            if(res_table_rd_reg[RES_STRT_H:RES_STRT_L] > alloc_res_start_reg) begin// Found the entry that will be after the new one
316	              if(res_table_rd_reg[PREV_ENTRY_H:PREV_ENTRY_L] == RES_TABLE_HEAD_POINTER_U) begin// if new entry will be the first entry
317	                alloc_done         <= 1'b0                ;
318	                new_entry_is_first <= 1'b1                ;
319	                a_state            <= ST_A_WRITE_NEW_ENTRY;
320	              end
321	              else begin
322	                alloc_done       <= 1'b0                  ;
323	                a_state          <= ST_A_UPDATE_PREV_ENTRY;
324	              end
325	            end
