451	        ST_D_UPDATE_NEXT_ENTRY : begin// In this cycle it is writing the previous entry, so we can use the addr_reg to get our the next entry addr
452	          if(rem_entry_is_first) begin
453	            dealloc_done <= 1'b1     ;
454	            d_state      <= ST_D_IDLE;
455	          end
456	          else if(rem_entry_is_last) begin
