754	        res_table_wr_reg <= {RES_TABLE_END_TABLE_U,res_table_rd_reg[PREV_ENTRY_H:RES_STRT_L]};
755	      end
756	      else begin
757	        res_table_rd_en  <= 1'b0                                                                                                  ;
758	        res_table_wr_en  <= 1'b1                                                                                                  ;
759	        res_addr_wg_slot <= res_table_wr_reg[NEXT_ENTRY_H:NEXT_ENTRY_L]                                                           ;
760	        res_table_wr_reg <= {res_table_rd_reg[NEXT_ENTRY_H:NEXT_ENTRY_L],res_addr_wg_slot,res_table_rd_reg[RES_SIZE_H:RES_STRT_L]};
761	      end
762	    end
763	
764	    else if(a_state == ST_A_IDLE && d_state == ST_D_IDLE && f_state == ST_F_FIRST_ITEM) begin
765	      if(res_table_rd_valid) begin
766	        if(res_table_rd_reg[NEXT_ENTRY_H:NEXT_ENTRY_L] != RES_TABLE_END_TABLE_U) begin// check if end of the table
767	          res_table_rd_en  <= 1'b1                                       ;              
768	          res_table_wr_en  <= 1'b0                                       ;
769	          res_addr_wg_slot <= res_table_rd_reg[NEXT_ENTRY_H:NEXT_ENTRY_L];
770	        end
771	        else begin
772	          res_table_rd_en <= 1'b0;              
773	          res_table_wr_en <= 1'b0;
774	        end
775	      end
776	      else begin
777	        res_table_rd_en  <= 1'b0            ; 
778	        res_table_wr_en  <= 1'b0            ;
779	        res_addr_wg_slot <= res_addr_wg_slot;
780	      end
781	    end
782	
783	    else if(a_state == ST_A_IDLE && d_state == ST_D_IDLE && f_state == ST_F_SEARCHING) begin
784	      if(res_table_rd_valid) begin
785	        if(res_table_rd_reg[NEXT_ENTRY_H:NEXT_ENTRY_L] != RES_TABLE_END_TABLE_U) begin// check if the next item is the last and if this is the max res size
786	          res_table_rd_en  <= 1'b1                                       ;              
787	          res_table_wr_en  <= 1'b0                                       ;
788	          res_addr_wg_slot <= res_table_rd_reg[NEXT_ENTRY_H:NEXT_ENTRY_L];
789	        end
790	        else begin
791	          res_table_rd_en <= 1'b0;              
792	          res_table_wr_en <= 1'b0;
793	        end
794	      end
795	      else begin
796	        res_table_rd_en  <= 1'b0            ; 
797	        res_table_wr_en  <= 1'b0            ;  
798	        res_addr_wg_slot <= res_addr_wg_slot;
799	      end
800	    end
801	
802	    else if(a_state == ST_A_IDLE && d_state == ST_D_IDLE && f_state == ST_F_LAST_ITEM) begin
803	      res_table_rd_en <= 1'b0;              
804	      res_table_wr_en <= 1'b0;
805	    end
806	
807	    else begin
808	      res_table_rd_en  <= 1'b0;              
809	      res_table_wr_en  <= 1'b0;            
810	      res_addr_wg_slot <= 'd0 ;        
811	      res_table_wr_reg <= 'd0 ;        
812	    end
813	  end
814	
815	  //datapath of the resource table
816	  always@(posedge clk or negedge rst_n) begin
817	    if(!rst_n) begin
818	      cu_initialized         <= 'd0;
819	      table_head_pointer     <= 'd0;
820	      cu_initialized_reg     <= 'd0;
821	      table_head_pointer_reg <= 'd0;
822	    end
823	    else if(alloc_res_en_reg || dealloc_res_en_reg) begin// Read the head pointer at the start
824	      cu_initialized_reg     <= cu_initialized[res_addr_cu_id]    ;
825	      table_head_pointer_reg <= table_head_pointer[(res_addr_cu_id+1)*WG_SLOT_ID_WIDTH_TABLE-1-:WG_SLOT_ID_WIDTH_TABLE];
826	    end
827	    else if(a_state == ST_A_WRITE_NEW_ENTRY && d_state == ST_D_IDLE && f_state == ST_F_IDLE) begin
828	      if(new_entry_is_first) begin
829	        table_head_pointer_reg <= alloc_wg_slot_id_reg;
830	      end
831	      else begin
832	        table_head_pointer_reg <= table_head_pointer_reg;
833	      end
834	    end
835	    else if(a_state == ST_A_IDLE && d_state == ST_D_READ_PREV_ENTRY && f_state == ST_F_IDLE) begin
836	      if(res_table_rd_valid) begin
837	        if(res_table_rd_reg[PREV_ENTRY_H:PREV_ENTRY_L] == RES_TABLE_HEAD_POINTER_U && res_table_rd_reg[NEXT_ENTRY_H:NEXT_ENTRY_L] == RES_TABLE_END_TABLE_U) begin
838	          table_head_pointer_reg <= RES_TABLE_END_TABLE_U;
839	        end
840	        else begin
841	          table_head_pointer_reg <= table_head_pointer_reg;
842	        end
843	      end
844	      else begin
845	        table_head_pointer_reg <= table_head_pointer_reg;
846	      end
847	    end
848	    else if(a_state == ST_A_IDLE && d_state == ST_D_UPDATE_NEXT_ENTRY && f_state == ST_F_IDLE) begin
849	      if(rem_entry_is_first) begin
850	        table_head_pointer_reg <= res_addr_wg_slot;
851	      end
852	      else begin
853	        table_head_pointer_reg <= table_head_pointer_reg;
854	      end
855	    end
856	    else if(alloc_done || dealloc_done) begin// Write the head pointer at the end
857	      cu_initialized[res_addr_cu_id]                                                          <= 1'b1                  ;
858	      table_head_pointer[(res_addr_cu_id+1)*WG_SLOT_ID_WIDTH_TABLE-1-:WG_SLOT_ID_WIDTH_TABLE] <= table_head_pointer_reg;
859	    end
860	    else begin
861	      cu_initialized         <= cu_initialized        ; 
862	      table_head_pointer     <= table_head_pointer    ;
863	      cu_initialized_reg     <= cu_initialized_reg    ;
864	      table_head_pointer_reg <= table_head_pointer_reg;
865	    end
866	  end
867	
868	  always@(posedge clk or negedge rst_n) begin
869	    if(!rst_n) begin
870	      res_table_rd_reg      <= 'd0;
871	      res_table_last_rd_reg <= 'd0;
872	      resource_table_ram    <= 'd0;
873	    end
874	    else if(res_table_rd_en) begin
875	      res_table_rd_reg      <= resource_table_ram[(`NUMBER_WF_SLOTS*res_addr_cu_id+res_addr_wg_slot+1)*TABLE_ENTRY_WIDTH-1-:TABLE_ENTRY_WIDTH];
876	      res_table_last_rd_reg <= res_table_rd_reg                                                                                               ;
877	    end
878	    else if(res_table_wr_en) begin
879	      resource_table_ram[(`NUMBER_WF_SLOTS*res_addr_cu_id+res_addr_wg_slot+1)*TABLE_ENTRY_WIDTH-1-:TABLE_ENTRY_WIDTH] <= res_table_wr_reg;
880	    end
881	    else begin
882	      res_table_rd_reg      <= res_table_rd_reg     ;  
883	      res_table_last_rd_reg <= res_table_last_rd_reg;
884	      resource_table_ram    <= resource_table_ram   ;
885	    end
886	  end
887	
888	  assign cam_biggest_space_size_o = res_table_max_size ;
889	  assign cam_biggest_space_addr_o = res_table_max_start;
890	
891	endmodule
892

